//---------------------------------------------------------------------------//
// Unit tests for tools/lina/plane
// Initial implementation generated by GitHub CoPilot (GPT-4.1)
//---------------------------------------------------------------------------//
#include "tools/lina/plane"

#include "tools/lina/line"
#include "tools/lina/vec"
#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
// TEST FIXTURES
//---------------------------------------------------------------------------//
// Helpers for clarity. Tools doesn't provide these aliases as they're never
// actually used, but we want to test them.
using vec3d = vec3<double>;
using line3d = line<double>;
using plane3d = plane<double>;

//---------------------------------------------------------------------------//
TEST(Plane, ConstructFromThreePointsFloat)
{
  vec3f p0(0.0f, 0.0f, 0.0f);
  vec3f p1(1.0f, 0.0f, 0.0f);
  vec3f p2(0.0f, 1.0f, 0.0f);
  plane<float> pl(p0, p1, p2);
  EXPECT_TRUE(pl.is_valid());
  EXPECT_FLOAT_EQ(pl.normal().x(), 0.0f);
  EXPECT_FLOAT_EQ(pl.normal().y(), 0.0f);
  EXPECT_FLOAT_EQ(pl.normal().z(), 1.0f);
  EXPECT_FLOAT_EQ(pl.distance_from_origin(), 0.0f);
}

TEST(Plane, ConstructFromThreePointsDouble)
{
  vec3d p0(0.0, 0.0, 0.0);
  vec3d p1(1.0, 0.0, 0.0);
  vec3d p2(0.0, 1.0, 0.0);
  plane<double> pl(p0, p1, p2);
  EXPECT_TRUE(pl.is_valid());
  EXPECT_DOUBLE_EQ(pl.normal().x(), 0.0);
  EXPECT_DOUBLE_EQ(pl.normal().y(), 0.0);
  EXPECT_DOUBLE_EQ(pl.normal().z(), 1.0);
  EXPECT_DOUBLE_EQ(pl.distance_from_origin(), 0.0);
}

TEST(Plane, ConstructFromNormalAndDistanceFloat)
{
  vec3f n(0.0f, 0.0f, 1.0f);
  plane<float> pl(n, 5.0f);
  EXPECT_TRUE(pl.is_valid());
  EXPECT_FLOAT_EQ(pl.normal().x(), 0.0f);
  EXPECT_FLOAT_EQ(pl.normal().y(), 0.0f);
  EXPECT_FLOAT_EQ(pl.normal().z(), 1.0f);
  EXPECT_FLOAT_EQ(pl.distance_from_origin(), 5.0f);
}

TEST(Plane, ConstructFromNormalAndDistanceDouble)
{
  vec3d n(0.0, 0.0, 1.0);
  plane3d pl(n, 5.0);
  EXPECT_TRUE(pl.is_valid());
  EXPECT_DOUBLE_EQ(pl.normal().x(), 0.0);
  EXPECT_DOUBLE_EQ(pl.normal().y(), 0.0);
  EXPECT_DOUBLE_EQ(pl.normal().z(), 1.0);
  EXPECT_DOUBLE_EQ(pl.distance_from_origin(), 5.0);
}

TEST(Plane, ConstructFromNormalAndPointFloat)
{
  vec3f n(0.0f, 0.0f, 1.0f);
  vec3f pt(0.0f, 0.0f, 2.0f);
  plane3f pl(n, pt);
  EXPECT_TRUE(pl.is_valid());
  EXPECT_FLOAT_EQ(pl.normal().z(), 1.0f);
  EXPECT_FLOAT_EQ(pl.distance_from_origin(), 2.0f);
}

TEST(Plane, ConstructFromNormalAndPointDouble)
{
  vec3d n(0.0, 0.0, 1.0);
  vec3d pt(0.0, 0.0, 2.0);
  plane3d pl(n, pt);
  EXPECT_TRUE(pl.is_valid());
  EXPECT_DOUBLE_EQ(pl.normal().z(), 1.0);
  EXPECT_DOUBLE_EQ(pl.distance_from_origin(), 2.0);
}

TEST(Plane, DistanceToPointFloat)
{
  plane3f pl(vec3f(0.0f, 0.0f, 1.0f), 2.0f);
  vec3f pt_above(0.0f, 0.0f, 5.0f);
  vec3f pt_on(0.0f, 0.0f, 2.0f);
  vec3f pt_below(0.0f, 0.0f, -1.0f);
  EXPECT_FLOAT_EQ(pl.distance(pt_above), 3.0f);
  EXPECT_FLOAT_EQ(pl.distance(pt_on), 0.0f);
  EXPECT_FLOAT_EQ(pl.distance(pt_below), -3.0f);
}

TEST(Plane, DistanceToPointDouble)
{
  plane3d pl(vec3d(0.0, 0.0, 1.0), 2.0);
  vec3d pt_above(0.0, 0.0, 5.0);
  vec3d pt_on(0.0, 0.0, 2.0);
  vec3d pt_below(0.0, 0.0, -1.0);
  EXPECT_DOUBLE_EQ(pl.distance(pt_above), 3.0);
  EXPECT_DOUBLE_EQ(pl.distance(pt_on), 0.0);
  EXPECT_DOUBLE_EQ(pl.distance(pt_below), -3.0);
}

TEST(Plane, IntersectLineFloat)
{
  plane3f pl(vec3f(0.0f, 0.0f, 1.0f), 2.0f);
  line3f l(vec3f(0.0f, 0.0f, 0.0f), vec3f(0.0f, 0.0f, 5.0f));
  vec3f intersection;
  EXPECT_TRUE(pl.intersect(l, intersection));
  // Intersection should be at z = 2
  EXPECT_FLOAT_EQ(intersection.x(), 0.0f);
  EXPECT_FLOAT_EQ(intersection.y(), 0.0f);
  EXPECT_FLOAT_EQ(intersection.z(), 2.0f);
}

TEST(Plane, IntersectLineDouble)
{
  plane3d pl(vec3d(0.0, 0.0, 1.0), 2.0);
  line3d l(vec3d(0.0, 0.0, 0.0), vec3d(0.0, 0.0, 5.0));
  vec3d intersection;
  EXPECT_TRUE(pl.intersect(l, intersection));
  EXPECT_DOUBLE_EQ(intersection.x(), 0.0);
  EXPECT_DOUBLE_EQ(intersection.y(), 0.0);
  EXPECT_DOUBLE_EQ(intersection.z(), 2.0);
}

TEST(Plane, ParallelLineNoIntersectionFloat)
{
  plane3f pl(vec3f(0.0f, 0.0f, 1.0f), 2.0f);
  line3f l(vec3f(0.0f, 0.0f, 0.0f), vec3f(1.0f, 0.0f, 0.0f));
  vec3f intersection;
  EXPECT_FALSE(pl.intersect(l, intersection));
}

TEST(Plane, ParallelLineNoIntersectionDouble)
{
  plane3d pl(vec3d(0.0, 0.0, 1.0), 2.0);
  line3d l(vec3d(0.0, 0.0, 0.0), vec3d(1.0, 0.0, 0.0));
  vec3d intersection;
  EXPECT_FALSE(pl.intersect(l, intersection));
}

//---------------------------------------------------------------------------//
}  // namespace tools
